<?php
declare(strict_types=1); require __DIR__.'/common.php'; if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET')respond(['error'=>'Método no permitido.'],405);$pdo=db();$plants=$pdo->query('SELECT id,name,botanical,category,price,image,light,water,season,difficulty,pet_note AS petNote,description FROM plants WHERE published=1 ORDER BY position,name')->fetchAll();foreach($plants as &$p)$p['price']=$p['price']===null?null:(int)$p['price'];$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM site_settings')->fetchAll()as$row)$settings[$row['setting_key']]=$row['setting_value'];$faqs=$pdo->query('SELECT id,question,answer,position FROM faqs WHERE published=1 ORDER BY position,id')->fetchAll();respond(['plants'=>$plants,'settings'=>$settings,'faqs'=>$faqs]);
